def safe_power(a, b):
    """
    Safe exponentiation with basic overflow protection.
    """

    try:
        result = a ** b

        # basic sanity check for infinities
        if result == float("inf") or result == float("-inf"):
            return None

        return result

    except (OverflowError, ValueError):
        return None

