code.raw:
def factorial(n):
    """
    Iterative factorial with validation.
    Returns None for invalid input.
    """

    if not isinstance(n, int):
        return None

    if n < 0:
        return None

    result = 1

    for i in range(2, n + 1):
        result *= i

    return result

